from marshmallow import Schema, fields, ValidationError, validates, EXCLUDE


class SignupSchema(Schema):
    class Meta:
        unknown = EXCLUDE

    username = fields.String(required=True)
    email = fields.Email(required=True)
    plan = fields.String(load_default="free", validate=lambda p: p in {"free", "pro", "team"})
    age = fields.Integer(validate=lambda n: 16 <= n <= 120)

    @validates("username")
    def validate_username(self, value, *, data_key=None):
        if not value.isalnum():
            raise ValidationError("Username must be alphanumeric.")


def validate_signup(data: dict) -> dict:
    """
    Validate sign-up data dict with required username and email,
    optional plan (default "free") and age (16 to 120).
    Drops unknown keys.
    Raises ValueError with .messages dict on validation errors.
    """
    try:
        return SignupSchema().load(data)
    except ValidationError as err:
        exc = ValueError("invalid signup data")
        exc.messages = err.messages
        raise exc
